import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import "./optimizevideo.css"; // Import CSS for styling

const OptimizeVideo = () => {
  const location = useLocation(); // Use React Router's useLocation to get passed state
  const [videoPath, setVideoPath] = useState("");
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (location.state) {
      const { message: responseMessage, results } = location.state;

      // Set the message
      setMessage(responseMessage);
      console.log("Received Result:", results)
      // Determine the video path to use
      const upscaledPath = results?.video_upscaling?.output_path || null;
      const audioProcessedPath = results?.audio_processing?.output_path || null;

      // Prefer the audio-processed path if both exist
      const finalPath = audioProcessedPath || upscaledPath;

      if (finalPath) {
        setVideoPath(`http://127.0.0.1:8000/media/${finalPath}`);
      }
    }
  }, [location.state]);

  const handlePreview = () => {
    if (videoPath) {
      alert("Playing video preview...");
    } else {
      alert("No video available for preview.");
    }
  };

  const handleDownload = () => {
    if (videoPath) {
      const link = document.createElement("a");
      link.href = videoPath;
      link.download = "optimized-video.mp4";
      link.click();
    } else {
      alert("No video available for download.");
    }
  };

  return (
    <div className="optimized-video-page">
      {/* Header Section */}
      <header className="page-header">
        <h1>Optimized Video Output</h1>
        <p>{message || "Your video has been optimized successfully. You can preview or download it below."}</p>
      </header>

      {/* Video Output Section */}
      <div className="video-output">
        {videoPath ? (
          <video
            className="optimized-video"
            controls
            src={videoPath}
            alt="Optimized Video Output"
          >
            Your browser does not support the video tag.
          </video>
        ) : (
          <p>No optimized video available.</p>
        )}

        {/* Action Buttons */}
        <div className="action-buttons">
          <button className="preview-button" onClick={handlePreview}>
            Preview
          </button>
          <button className="download-button" onClick={handleDownload}>
            Download
          </button>
        </div>
      </div>
    </div>
  );
};

export default OptimizeVideo;
